    "p.a2-06.1": "¿Qué vas a llevar a la fiesta?",
    "p.a2-06.2": "¿Puedo probarme esto?",
    "p.a2-06.3": "Te queda muy bien.",
    "p.a2-06.4": "Me queda demasiado grande.",
    "p.a2-06.5": "¿Cómo es él físicamente?",
    "p.a2-06.6": "Ella tiene el pelo largo y oscuro.",
    "p.a2-06.7": "Él es más alto que yo.",
    "p.a2-06.8": "Este es mejor que ese.",
    "p.a2-06.9": "Ella es la mujer más elegante de la oficina.",
    "p.a2-06.10": "Él lleva gafas.",
    "p.a2-06.11": "Lleva un abrigo, hace frío afuera.",
    "p.a2-06.12": "¡Te ves genial!",
    "s.a2-06.1": "Hoy llevo vaqueros, una camiseta blanca y una chaqueta.",
    "s.a2-06.2": "Mi hermana es más baja que yo, pero es más fuerte.",
    "s.a2-06.3": "Este vestido es más elegante que la falda.",
    "s.a2-06.4": "Él es un hombre alto y delgado, con el pelo rubio y gafas.",
    "s.a2-06.5": "Estos zapatos son mejores que esos, pero más caros.",
    "s.a2-06.6": "En invierno llevamos abrigo, sombrero y bufanda.",
    "s.a2-06.7": "Mi abuela es la persona más amable de la familia.",
    "s.a2-06.8": "Me probé los pantalones, pero no me quedaban bien.",
    "s.a2-06.9": "El tiempo hoy es peor que ayer.",
    "s.a2-06.10": "Los calcetines negros son más baratos que los rojos.",
    "s.a2-06.11": "A ella le gusta la moda y siempre lleva ropa bonita.",
    "s.a2-06.12": "Mi hermano es el estudiante más guapo de su clase.",
    "d.a2-06.1": "Michal, ¿quién es la mujer que está al lado de tu jefe?",
    "d.a2-06.2": "¿Cuál? ¿La alta del pelo largo y oscuro?",
    "d.a2-06.3": "No, la más baja, con gafas y un vestido rojo.",
    "d.a2-06.4": "Ah, esa es Dana, nuestra nueva colega. Es muy amable.",
    "d.a2-06.5": "Es muy elegante. Me gusta su chaqueta.",
    "d.a2-06.6": "Sí, le encanta la moda. ¡Siempre lleva mejor ropa que yo!",
    "d.a2-06.7": "¿Y quién es el hombre del pelo rubio y la camisa azul?",
    "d.a2-06.8": "Ese es su esposo. Es mayor que ella, creo.",
    "d.a2-06.9": "Parece una persona agradable.",
    "d.a2-06.10": "Lo es. Ven, te lo presento.",
    "m.a2-06": "Mi amigo ... es alto / bajo y tiene el pelo ... . Normalmente lleva ... . Él es más alto que yo, pero yo soy más ... que él. Es la persona más ... que conozco.",
