    "p.a2-07.1": "¡Adivina lo que me pasó!",
    "p.a2-07.2": "Había una vez...",
    "p.a2-07.3": "¿Qué pasó después?",
    "p.a2-07.4": "De repente, se apagaron las luces.",
    "p.a2-07.5": "Nací en 1990.",
    "p.a2-07.6": "Crecí en un pueblo pequeño.",
    "p.a2-07.7": "Por suerte, nadie resultó herido.",
    "p.a2-07.8": "¡Estás bromeando!",
    "p.a2-07.9": "No podía creerlo.",
    "p.a2-07.10": "Al final, todo salió bien.",
    "p.a2-07.11": "Mientras dormía, sonó el teléfono.",
    "p.a2-07.12": "Cuéntame toda la historia.",
    "s.a2-07.1": "Cuando era niño, vivíamos cerca del mar.",
    "s.a2-07.2": "Primero perdí mis llaves, luego las encontré en mi bolso.",
    "s.a2-07.3": "Mientras comíamos, mi hermano contó una historia larga.",
    "s.a2-07.4": "De repente ella se cayó y se rompió el brazo.",
    "s.a2-07.5": "Mis padres se casaron hace treinta años.",
    "s.a2-07.6": "Él dijo que vio a una persona famosa en el aeropuerto.",
    "s.a2-07.7": "Ganamos y todos rieron y cantaron.",
    "s.a2-07.8": "Hubo un accidente en la carretera, pero por suerte nadie resultó herido.",
    "s.a2-07.9": "Fue una aventura maravillosa del principio al final.",
    "s.a2-07.10": "Desgraciadamente, cuando llegamos, la fiesta ya había terminado.",
    "s.a2-07.11": "El bebé lloró toda la noche, y todavía estamos cansados.",
    "s.a2-07.12": "En ese momento entendí que era una fiesta sorpresa.",
    "d.a2-07.1": "Abuela, cuéntame una historia de tu infancia.",
    "d.a2-07.2": "Una vez, cuando tenía ocho años, fui a la playa con mi hermano.",
    "d.a2-07.3": "¿Solo ustedes dos? ¿Sin sus padres?",
    "d.a2-07.4": "¡Sí! Mientras nadábamos, de repente empezó a llover.",
    "d.a2-07.5": "¿Qué pasó entonces?",
    "d.a2-07.6": "Corrimos a casa, pero yo me caí y perdí un zapato.",
    "d.a2-07.7": "¡Oh, no! ¿Lo encontraste?",
    "d.a2-07.8": "No, desgraciadamente. Mi madre estaba enojada, pero luego se rio.",
    "d.a2-07.9": "¿Y tu hermano?",
    "d.a2-07.10": "¡Todavía cuenta esta historia en cada cena familiar!",
    "d.a2-07.11": "Me encantan tus historias, abuela.",
    "m.a2-07": "El ... pasado yo estaba ... cuando de repente ... . Primero ... , luego ... . Por suerte, ... . Al final ... .",
