    "w.b2-02.cutting-edge": "de vanguardia",
    "p.b2-02.1": "Los resultados hablan por sí mismos.",
    "p.b2-02.2": "En teoría funciona, pero en la práctica es complicado.",
    "p.b2-02.3": "Todavía está en fase experimental.",
    "p.b2-02.4": "Los datos no respaldan esa conclusión.",
    "p.b2-02.5": "En caso de duda, repite la prueba.",
    "p.b2-02.6": "La tecnología es un arma de doble filo.",
    "p.b2-02.7": "Mi teléfono está prácticamente obsoleto.",
    "p.b2-02.8": "Haz una copia de seguridad de tus archivos por si el sistema falla.",
    "p.b2-02.9": "Nadie podría haber predicho esto.",
    "p.b2-02.10": "Los científicos están a punto de lograr un avance.",
    "p.b2-02.11": "Siempre que sea seguro, no me importa usarlo.",
    "s.b2-02.1": "Si calientas el agua a cien grados, hierve.",
    "s.b2-02.2": "Si el experimento tiene éxito, el equipo publicará los datos el año que viene.",
    "s.b2-02.3": "Si los científicos tuvieran más financiación, realizarían más experimentos.",
    "s.b2-02.4": "Si el satélite no se hubiera lanzado, no habríamos observado el fenómeno.",
    "s.b2-02.5": "A menos que el algoritmo sea preciso, las predicciones son inútiles.",
    "s.b2-02.6": "De haberse demostrado la hipótesis, habría cambiado la teoría por completo.",
    "s.b2-02.7": "La inteligencia artificial puede analizar datos más rápido que cualquier humano.",
    "s.b2-02.8": "El avance en la investigación genética se logró en un laboratorio pequeño.",
    "s.b2-02.9": "Si los hackers hubieran entrado en el sistema, millones de cuentas estarían en riesgo.",
    "s.b2-02.10": "La automatización dejará obsoletos muchos empleos en una década.",
    "s.b2-02.11": "Los científicos midieron las partículas con instrumentos de vanguardia.",
    "s.b2-02.12": "Si yo fuera científico, estudiaría cómo se reparan las células.",
    "d.b2-02.1": "Dra. Adler, su equipo anunció un avance la semana pasada. ¿Qué descubrieron exactamente?",
    "d.b2-02.2": "Desarrollamos un algoritmo que predice cómo reaccionan ciertas células a nuevos fármacos.",
    "d.b2-02.3": "¿Qué tan preciso es?",
    "d.b2-02.4": "En nuestros experimentos, alrededor del noventa por ciento. Si los datos son buenos, las predicciones son fiables.",
    "d.b2-02.5": "¿Qué pasaría si un hospital confiara en él y se equivocara?",
    "d.b2-02.6": "Por eso los médicos siempre tomarán la decisión final. La herramienta solo los apoya.",
    "d.b2-02.7": "Algunas personas temen que la inteligencia artificial deje obsoletos a los científicos.",
    "d.b2-02.8": "Si eso fuera cierto, habríamos dejado de contratar investigadores. En cambio, contratamos diez más.",
    "d.b2-02.9": "¿Y la ciberseguridad? Los datos de los pacientes son sensibles.",
    "d.b2-02.10": "A menos que los datos estén cifrados y almacenados localmente, no los usamos.",
    "d.b2-02.11": "¿Qué sigue para el laboratorio?",
    "d.b2-02.12": "Si conseguimos financiación, realizaremos un ensayo más grande la próxima primavera.",
