    "w.b2-03.efficiency": "la eficiencia",
    "p.b2-03.1": "El negocio está en auge.",
    "p.b2-03.2": "Estamos operando con pérdidas.",
    "p.b2-03.3": "Los precios se han disparado.",
    "p.b2-03.4": "Vamos al grano.",
    "p.b2-03.5": "La empresa quebró el año pasado.",
    "p.b2-03.6": "En este momento la demanda supera la oferta.",
    "p.b2-03.7": "Es una inversión arriesgada, pero los rendimientos podrían ser altos.",
    "p.b2-03.8": "Por un lado..., por otro lado...",
    "p.b2-03.9": "Necesitamos recortar costos en todas las áreas.",
    "p.b2-03.10": "El acuerdo se vino abajo en el último momento.",
    "p.b2-03.11": "A largo plazo, dará sus frutos.",
    "p.b2-03.12": "Nuestra cuota de mercado se ha duplicado.",
    "s.b2-03.1": "La inflación subió bruscamente; como resultado, los consumidores gastaron menos.",
    "s.b2-03.2": "La startup lanzó una nueva marca; sin embargo, las ventas siguieron siendo bajas.",
    "s.b2-03.3": "Aunque la economía está creciendo, muchas familias todavía pasan dificultades.",
    "s.b2-03.4": "La fusión reducirá los costos; además, mejorará la eficiencia.",
    "s.b2-03.5": "En primer lugar, necesitamos inversores; en segundo lugar, necesitamos un presupuesto realista.",
    "s.b2-03.6": "El país exporta tecnología, mientras que importa la mayor parte de sus alimentos.",
    "s.b2-03.7": "A pesar de la recesión, la empresa obtuvo una pequeña ganancia.",
    "s.b2-03.8": "El pronóstico prevé un crecimiento lento; por lo tanto, deberíamos expandirnos con cuidado.",
    "s.b2-03.9": "Los precios de las acciones cayeron tras la quiebra del mayor proveedor.",
    "s.b2-03.10": "La competencia mantiene los precios bajos, lo que al final beneficia a los consumidores.",
    "s.b2-03.11": "La emprendedora financió el proyecto con sus propios ahorros.",
    "s.b2-03.12": "Por último, recuerden que todo acuerdo implica algún riesgo.",
    "d.b2-03.1": "Gracias por su tiempo. Nuestra startup fabrica envases reutilizables para restaurantes.",
    "d.b2-03.2": "Interesante. ¿Cómo es la demanda?",
    "d.b2-03.3": "Fuerte y creciente. En primer lugar, las nuevas normativas prohíben el plástico de un solo uso; en segundo lugar, los consumidores prefieren marcas sostenibles.",
    "d.b2-03.4": "Sin embargo, sus costos de producción parecen altos. ¿Cómo obtendrán ganancias?",
    "d.b2-03.5": "Al principio operaremos con una pequeña pérdida. En cuanto nos expandamos, la eficiencia mejorará y los costos bajarán.",
    "d.b2-03.6": "¿Y la competencia? Hay empresas más grandes en este mercado.",
    "d.b2-03.7": "Cierto, pero ellas importan sus productos, mientras que nosotros fabricamos localmente y entregamos más rápido.",
    "d.b2-03.8": "¿Cuánta financiación buscan?",
    "d.b2-03.9": "Dos millones, a cambio del quince por ciento de las acciones.",
    "d.b2-03.10": "Es ambicioso. Además, el pronóstico supone que no habrá recesión.",
    "d.b2-03.11": "Hemos preparado un segundo presupuesto para una economía más lenta. Aquí está.",
    "d.b2-03.12": "Bien. Envíeme el plan completo y hablamos la semana que viene.",
    "m.b2-03": "La economía de ... está actualmente ... . En primer lugar, ... . Como resultado, ... . Sin embargo, ... . Además, ... . Por lo tanto, a largo plazo ... .",
