    "w.b2-04.tragedy": "la tragedia",
    "p.b2-04.1": "Está abierto a interpretación.",
    "p.b2-04.2": "La novela fue un superventas inmediato.",
    "p.b2-04.3": "No podía dejar el libro.",
    "p.b2-04.4": "El cuadro me dejó una profunda impresión.",
    "p.b2-04.5": "La melodía se me quedó grabada durante días.",
    "p.b2-04.6": "Tiene una imaginación muy viva.",
    "p.b2-04.7": "La exposición bien merece una visita.",
    "p.b2-04.8": "¿Qué quiere decir el autor con esto?",
    "p.b2-04.9": "El final me tomó completamente por sorpresa.",
    "p.b2-04.10": "El arte es cuestión de gustos.",
    "p.b2-04.11": "La letra es más importante que la música.",
    "s.b2-04.1": "La publicación de su primera novela le cambió la vida.",
    "s.b2-04.2": "La representación de la pobreza en la película es dolorosamente realista.",
    "s.b2-04.3": "La interpretación de la escultura por parte del curador sorprendió a muchos visitantes.",
    "s.b2-04.4": "La soledad del protagonista es el tema central de la novela.",
    "s.b2-04.5": "La composición de la sinfonía le llevó al compositor casi una década.",
    "s.b2-04.6": "El poeta utiliza el mar como metáfora de la memoria.",
    "s.b2-04.7": "La llegada del director al escenario fue recibida con un fuerte aplauso.",
    "s.b2-04.8": "El arte abstracto exige la participación activa del espectador.",
    "s.b2-04.9": "La falta de fiabilidad del narrador da a la historia su tensión.",
    "s.b2-04.10": "El retrato revela la tristeza tras la sonrisa del rey.",
    "s.b2-04.11": "El dramaturgo encontró inspiración en una antigua tragedia griega.",
    "s.b2-04.12": "La decisión de la galería de exponer a artistas jóvenes fue ampliamente elogiada.",
    "d.b2-04.1": "Bueno, ¿qué les pareció la novela?",
    "d.b2-04.2": "Sinceramente, me costó simpatizar con el protagonista, pero la escritura es hermosa.",
    "d.b2-04.3": "Estoy de acuerdo con lo de la escritura. El uso de la metáfora por parte de la autora es notable.",
    "d.b2-04.4": "El río que vuelve una y otra vez, por ejemplo. ¿Es una metáfora del tiempo?",
    "d.b2-04.5": "Esa es una interpretación. Yo lo leí como la culpa del narrador.",
    "d.b2-04.6": "Interesante. El tema de la culpa sí atraviesa todo el libro.",
    "d.b2-04.7": "¿Sabías que un dramaturgo muy conocido la está adaptando para el teatro?",
    "d.b2-04.8": "¿De verdad? Me pregunto cómo representarán las escenas de los sueños.",
    "d.b2-04.9": "Probablemente con música. La autora dijo que el ritmo le importaba más que la trama.",
    "d.b2-04.10": "Eso explica por qué en algunas partes se lee como poesía.",
    "d.b2-04.11": "¿Elegimos algo más ligero para el mes que viene?",
    "d.b2-04.12": "Sí, por favor. Una comedia, o al menos no otra tragedia.",
    "m.b2-04": "La exposición ofrece una representación poco común de ... . La elección de ... por parte del curador crea ... . De especial interés es ... . La combinación de ... y ... da como resultado ... . En conjunto, ... .",
