    "p.b2-05.1": "Inocente hasta que se demuestre lo contrario.",
    "p.b2-05.2": "Negó todos los cargos.",
    "p.b2-05.3": "El jurado llegó a un veredicto.",
    "p.b2-05.4": "Te llevaré a los tribunales.",
    "p.b2-05.5": "Le pusieron una multa por estacionar ilegalmente.",
    "p.b2-05.6": "Todos son iguales ante la ley.",
    "p.b2-05.7": "El caso fue desestimado por falta de pruebas.",
    "p.b2-05.8": "¿Eso es siquiera legal?",
    "p.b2-05.9": "El abogado instó a su cliente a guardar silencio.",
    "p.b2-05.10": "Tiene derecho a guardar silencio.",
    "p.b2-05.11": "El acusado fue declarado no culpable.",
    "s.b2-05.1": "El acusado afirmó que había estado en casa esa noche.",
    "s.b2-05.2": "La testigo admitió que no había visto la cara del hombre.",
    "s.b2-05.3": "El juez preguntó a la testigo si reconocía al acusado.",
    "s.b2-05.4": "El abogado insistió en que su cliente era inocente del fraude.",
    "s.b2-05.5": "La policía advirtió a los vecinos que no dejaran las puertas sin cerrar.",
    "s.b2-05.6": "La empresa fue demandada por infringir la normativa de privacidad.",
    "s.b2-05.7": "El ministro negó que la nueva legislación fuera a limitar ningún derecho.",
    "s.b2-05.8": "El tribunal dictaminó que la prohibición de la protesta era inconstitucional.",
    "s.b2-05.9": "Tras el veredicto, el acusado anunció que apelaría.",
    "s.b2-05.10": "Todo ciudadano tiene derecho a un juicio justo según la constitución.",
    "s.b2-05.11": "La investigación reveló pruebas de discriminación contra los trabajadores mayores.",
    "s.b2-05.12": "La reportera dijo que el hombre había sido condenado por un delito grave.",
    "d.b2-05.1": "Noa, estuviste en la sala del tribunal esta mañana. ¿Qué pasó?",
    "d.b2-05.2": "El juicio comenzó con la fiscalía presentando nuevas pruebas contra el acusado.",
    "d.b2-05.3": "¿Qué dijo el acusado?",
    "d.b2-05.4": "Insistió en que era inocente y afirmó que los documentos habían sido falsificados.",
    "d.b2-05.5": "¿Declaró algún testigo?",
    "d.b2-05.6": "Sí. Una exempleada admitió que había firmado los contratos sin leerlos.",
    "d.b2-05.7": "¿Cómo reaccionó el juez?",
    "d.b2-05.8": "Advirtió a ambas partes que no hablaran con la prensa y preguntó si se presentarían más pruebas.",
    "d.b2-05.9": "¿Se espera un veredicto pronto?",
    "d.b2-05.10": "Los abogados me dijeron que el juicio probablemente duraría otras tres semanas.",
    "d.b2-05.11": "¿Y si lo condenan por fraude?",
    "d.b2-05.12": "Su abogado ya ha anunciado que apelarían.",
