    "w.b2-06.deforestation": "la deforestación",
    "w.b2-06.biodiversity": "la biodiversidad",
    "w.b2-06.global-warming": "el calentamiento global",
    "w.b2-06.threat": "la amenaza",
    "w.b2-06.to-tackle": "abordar",
    "w.b2-06.consequence": "la consecuencia",
    "w.b2-06.to-affect": "afectar",
    "w.b2-06.vulnerable": "vulnerable",
    "w.b2-06.to-flee": "huir",
    "p.b2-06.1": "Es un problema global que necesita una solución global.",
    "p.b2-06.2": "Necesitamos crear conciencia.",
    "p.b2-06.3": "Millones no tienen acceso a agua limpia.",
    "p.b2-06.4": "Piensa globalmente, actúa localmente.",
    "p.b2-06.5": "La brecha entre ricos y pobres se está ampliando.",
    "p.b2-06.6": "Se nos acaba el tiempo.",
    "p.b2-06.7": "Toda donación cuenta, por pequeña que sea.",
    "p.b2-06.8": "Las conversaciones terminaron sin acuerdo.",
    "p.b2-06.9": "Es una gota en el océano.",
    "p.b2-06.10": "No podemos permitirnos ignorarlo.",
    "p.b2-06.11": "Prevenir es más barato que curar.",
    "s.b2-06.1": "Ante una sequía severa, el gobierno pidió ayuda humanitaria.",
    "s.b2-06.2": "Firmado en 2015, el tratado busca limitar el calentamiento global.",
    "s.b2-06.3": "Donar a una organización benéfica es una forma de abordar la desigualdad.",
    "s.b2-06.4": "Habiendo huido del conflicto, las familias viven ahora en refugios temporales.",
    "s.b2-06.5": "La deforestación destruye la biodiversidad, afectando a millones de especies.",
    "s.b2-06.6": "Las sanciones impuestas el año pasado han tenido consecuencias graves.",
    "s.b2-06.7": "Propagándose rápidamente a través de las fronteras, la pandemia afectó a todos los países.",
    "s.b2-06.8": "Los activistas esperan que crear conciencia lleve a un cambio real.",
    "s.b2-06.9": "El embajador advirtió que la diplomacia por sí sola no pondría fin al conflicto.",
    "s.b2-06.10": "Mejorar la infraestructura es esencial para el desarrollo de las regiones pobres.",
    "s.b2-06.11": "Las poblaciones vulnerables son las que más sufren los efectos de la globalización.",
    "s.b2-06.12": "Sin acceso a la educación, los niños siguen atrapados en la pobreza.",
    "d.b2-06.1": "Dr. Mansour, ¿qué tan grave es hoy la amenaza del calentamiento global?",
    "d.b2-06.2": "Extremadamente grave. Habiendo estudiado los datos durante veinte años, puedo decir que los cambios son más rápidos de lo previsto.",
    "d.b2-06.3": "Yonatan, su organización se centra en la deforestación. ¿Por qué?",
    "d.b2-06.4": "Porque talar los bosques destruye la biodiversidad y libera carbono al mismo tiempo.",
    "d.b2-06.5": "¿Qué puede hacer la gente común?",
    "d.b2-06.6": "Donar ayuda, pero crear conciencia y votar por las políticas correctas importa más.",
    "d.b2-06.7": "Estoy de acuerdo. Los gobiernos responden a la presión, como vimos con el tratado firmado el año pasado.",
    "d.b2-06.8": "Algunos sostienen que las sanciones a los países contaminantes serían más eficaces.",
    "d.b2-06.9": "Imponer sanciones sin ofrecer ayuda suele perjudicar a las poblaciones más vulnerables.",
    "d.b2-06.10": "Exactamente. La diplomacia y el desarrollo deben ir de la mano.",
    "d.b2-06.11": "¿Hay alguna razón para la esperanza?",
    "d.b2-06.12": "Sí. La energía renovable se está extendiendo más rápido de lo que nadie esperaba hace diez años.",
    "m.b2-06": "Habiendo identificado ... como una amenaza importante, proponemos ... . Financiado por ..., el proyecto ... . Trabajando con las comunidades locales, buscamos ... . Reducir ... también ... .",
