    "w.c1-01.whereas": "mientras que",
    "p.c1-01.1": "Es un punto válido, pero pierde de vista el panorama general.",
    "p.c1-01.2": "Hay que admitir que las pruebas son limitadas.",
    "p.c1-01.3": "Permítanme hacer de abogado del diablo por un momento.",
    "p.c1-01.4": "Entiendo su punto, pero no estoy convencido.",
    "p.c1-01.5": "Correlación no implica causalidad.",
    "p.c1-01.6": "Se está contradiciendo.",
    "p.c1-01.7": "Aceptemos que no estamos de acuerdo.",
    "p.c1-01.8": "La carga de la prueba recae sobre usted.",
    "p.c1-01.9": "Ese argumento simplemente no se sostiene.",
    "p.c1-01.10": "Con todo respeto, eso no viene al caso.",
    "p.c1-01.11": "Lo que importa aquí es el efecto a largo plazo.",
    "p.c1-01.12": "En conjunto, los beneficios pesan más que los costos.",
    "s.c1-01.1": "Aunque su afirmación suena persuasiva, la premisa que hay detrás es falsa.",
    "s.c1-01.2": "Es cierto que la política es polémica; no obstante, ha reducido la pobreza.",
    "s.c1-01.3": "Es la falta de pruebas lo que socava todo su argumento.",
    "s.c1-01.4": "Concedo ese punto, mientras que la conclusión la sigo rechazando.",
    "s.c1-01.5": "Una postura coherente reconoce los contraargumentos en lugar de ignorarlos.",
    "s.c1-01.6": "Aun cuando suponemos buenas intenciones, el sesgo afecta a cada decisión.",
    "s.c1-01.7": "Lo que hace peligrosa a una falacia es que parece lógica.",
    "s.c1-01.8": "Ella refutó la afirmación del oponente con una sola estadística.",
    "s.c1-01.9": "Abogar por el cambio es fácil; justificar sus costos es más difícil.",
    "s.c1-01.10": "Hay una clara contradicción entre su premisa y su conclusión.",
    "s.c1-01.11": "El consenso científico no significa que el debate esté cerrado para siempre.",
    "s.c1-01.12": "Al contrario, los datos refuerzan la afirmación en vez de debilitarla.",
    "d.c1-01.1": "Omri, usted defiende el voto obligatorio. Su afirmación inicial, por favor.",
    "d.c1-01.2": "La democracia depende de la participación. Cuando la mitad de la población se queda en casa, el resultado refleja una muestra sesgada, no la voluntad popular.",
    "d.c1-01.3": "Leah, su respuesta.",
    "d.c1-01.4": "Hay que admitir que la baja participación es un problema. No obstante, obligar a la gente a votar socava la misma libertad que las elecciones deben proteger.",
    "d.c1-01.5": "Concedo que la libertad importa. Sin embargo, ya aceptamos impuestos obligatorios y el deber de ser jurado, mientras que votar toma diez minutos.",
    "d.c1-01.6": "Esa es una comparación falsa. Los impuestos financian servicios; un voto forzado produce elecciones al azar de votantes desinformados.",
    "d.c1-01.7": "Omri, ¿cómo responde al contraargumento sobre los votantes desinformados?",
    "d.c1-01.8": "Lo que muestran los datos de Australia es que el voto obligatorio en realidad aumenta el conocimiento político con el tiempo.",
    "d.c1-01.9": "Un solo país difícilmente constituye un consenso. Además, está suponiendo que el efecto sería el mismo aquí.",
    "d.c1-01.10": "Es cierto, pero la alternativa, no hacer nada, claramente ha fracasado.",
    "d.c1-01.11": "Declaraciones finales. Leah primero.",
    "d.c1-01.12": "En conjunto, los costos para la libertad pesan más que los beneficios inciertos. Persuadan a la gente para que vote; no la obliguen.",
    "m.c1-01": "A menudo se afirma que ... . Hay que admitir que ... . No obstante, lo que muestran las pruebas es que ... . Mientras que los opositores sostienen ..., esto pasa por alto ... . En conjunto, ... .",
