    "w.c1-02.rational": "racional",
    "p.c1-02.1": "Todo está en tu cabeza.",
    "p.c1-02.2": "Las viejas costumbres nunca mueren.",
    "p.c1-02.3": "Ella tiende a darle demasiadas vueltas a las cosas.",
    "p.c1-02.4": "Presumiblemente, el estrés tuvo algo que ver.",
    "p.c1-02.5": "Debe de haber estado bajo una presión enorme.",
    "p.c1-02.6": "Hasta cierto punto, todos tenemos sesgos.",
    "p.c1-02.7": "No pude resistir la tentación.",
    "p.c1-02.8": "Parece que las recompensas funcionan mejor que el castigo.",
    "p.c1-02.9": "No saques conclusiones precipitadas.",
    "p.c1-02.10": "Podría decirse que la personalidad la moldea más el entorno que los genes.",
    "p.c1-02.11": "No podías haberlo sabido en ese momento.",
    "s.c1-02.1": "Las personas con alta autoestima pueden afrontar mejor las críticas.",
    "s.c1-02.2": "La procrastinación parece estar vinculada a la ansiedad más que a la pereza.",
    "s.c1-02.3": "Las personas extrovertidas tienden a buscar recompensas en situaciones sociales.",
    "s.c1-02.4": "El sujeto podría haber reprimido el recuerdo durante años.",
    "s.c1-02.5": "La presión social podría explicar, hasta cierto punto, por qué los adolescentes asumen riesgos.",
    "s.c1-02.6": "Podría decirse que nuestra percepción está moldeada por prejuicios subconscientes.",
    "s.c1-02.7": "Los incentivos presumiblemente funcionan solo cuando la meta parece alcanzable.",
    "s.c1-02.8": "La resiliencia parece depender en parte de las relaciones tempranas.",
    "s.c1-02.9": "No puede haber actuado por impulso; el plan era demasiado detallado.",
    "s.c1-02.10": "La terapia puede ayudar a los pacientes a reconocer la manipulación en sus relaciones.",
    "s.c1-02.11": "La intuición no siempre es irracional; a menudo refleja experiencia.",
    "s.c1-02.12": "Una mentalidad de crecimiento aparentemente mejora el rendimiento cognitivo en los niños.",
    "d.c1-02.1": "Dra. Peretz, ¿por qué las personas inteligentes toman decisiones irracionales?",
    "d.c1-02.2": "La inteligencia y la racionalidad son rasgos distintos. Las personas listas quizá simplemente sean mejores justificando sus impulsos.",
    "d.c1-02.3": "¿Entonces la fuerza de voluntad no es la respuesta?",
    "d.c1-02.4": "Solo hasta cierto punto. La fuerza de voluntad tiende a agotarse; un entorno de apoyo parece importar más.",
    "d.c1-02.5": "Su investigación sobre la procrastinación sorprendió a mucha gente.",
    "d.c1-02.6": "Presumiblemente porque suponemos que los procrastinadores son perezosos. Nuestros datos sugieren que a menudo son perfeccionistas ansiosos.",
    "d.c1-02.7": "¿Podrían las redes sociales estar empeorando esto?",
    "d.c1-02.8": "Es posible. La comparación constante parece reducir la autoestima, sobre todo entre adolescentes expuestos a la presión social.",
    "d.c1-02.9": "¿Hay algo que construya resiliencia de forma fiable?",
    "d.c1-02.10": "Podría decirse que la empatía de un adulto de confianza. Las pruebas no son concluyentes, pero son consistentes.",
    "d.c1-02.11": "¿Algún consejo final para nuestros lectores?",
    "d.c1-02.12": "Traten su intuición como una hipótesis, no como un veredicto. Luego compruébenla.",
    "m.c1-02": "Las investigaciones sugieren que ... tiende a ... . Esto puede deberse a que ... . Hasta cierto punto, ... . Parece que ..., aunque las pruebas son ... . Presumiblemente, ... .",
