    "w.c1-03.turning-point": "el punto de inflexión",
    "p.c1-03.1": "La historia se repite.",
    "p.c1-03.2": "Quienes olvidan el pasado están condenados a repetirlo.",
    "p.c1-03.3": "Marcó un punto de inflexión en la historia europea.",
    "p.c1-03.4": "Visto en retrospectiva, el derrumbe era inevitable.",
    "p.c1-03.5": "El fin justifica los medios, ¿o no?",
    "p.c1-03.6": "Pienso, luego existo.",
    "p.c1-03.7": "Conócete a ti mismo.",
    "p.c1-03.8": "Eso plantea más preguntas de las que responde.",
    "p.c1-03.9": "La historia la escriben los vencedores.",
    "p.c1-03.10": "No solo cayó el imperio, sino que su lengua también desapareció.",
    "p.c1-03.11": "¿Existe realmente el libre albedrío?",
    "s.c1-03.1": "Nunca antes se había derrumbado un imperio tan rápido y tan por completo.",
    "s.c1-03.2": "No solo puso fin la revolución a la esclavitud, sino que también redefinió la ciudadanía.",
    "s.c1-03.3": "Como los archivos fueron destruidos, los historiadores deben interpretar fragmentos.",
    "s.c1-03.4": "Solo después de la independencia empezó el país a escribir su propia historia.",
    "s.c1-03.5": "Los filósofos antiguos contemplaban si la virtud podía enseñarse.",
    "s.c1-03.6": "Aunque la razón guía la ética, la emoción a menudo decide nuestra moral.",
    "s.c1-03.7": "De no haber sido derrocado el rey, la era de los imperios podría haber continuado.",
    "s.c1-03.8": "El escepticismo, lejos de negar el conocimiento, pregunta cómo lo justificamos.",
    "s.c1-03.9": "Tan poderosa era la ideología que millones la aceptaron sin cuestionarla.",
    "s.c1-03.10": "La paradoja del libre albedrío es que nos sentimos libres y, sin embargo, actuamos de forma predecible.",
    "s.c1-03.11": "Toda civilización que conquistó a sus vecinos acabó enfrentando el mismo destino.",
    "s.c1-03.12": "Lo que los filósofos llaman existencia, los historiadores lo llaman contexto.",
    "d.c1-03.1": "¿Por qué se derrumbó el Imperio romano? Shai, empecemos con usted.",
    "d.c1-03.2": "Tradicionalmente, los historiadores culparon a las invasiones. No solo eran las fronteras demasiado largas, sino que el ejército también estaba agotado.",
    "d.c1-03.3": "Mor, ¿usted no está de acuerdo?",
    "d.c1-03.4": "En parte. De haber estado sana la economía, el imperio podría haber sobrevivido a las invasiones, como lo había hecho antes.",
    "d.c1-03.5": "¿Entonces interpreta el derrumbe como económico más que militar?",
    "d.c1-03.6": "Sí. La esclavitud hizo innecesaria la innovación, y cuando cesaron las conquistas, cesó también el suministro de esclavos.",
    "d.c1-03.7": "Esa es una lectura moderna, sin embargo. Los propios escritores antiguos culpaban a una pérdida de virtud.",
    "d.c1-03.8": "Lo que plantea una pregunta filosófica: ¿puede una civilización decaer moralmente?",
    "d.c1-03.9": "Solo si suponemos que la moral es más que ideología, lo que los escépticos negarían.",
    "d.c1-03.10": "Sin embargo, sin una ética compartida, ninguna sociedad se mantiene unida por mucho tiempo.",
    "d.c1-03.11": "Excelente. Para la semana que viene, lean las fuentes del archivo y decidan qué punto de inflexión les parece más convincente.",
    "d.c1-03.12": "Y si la caída fue inevitable, o si el libre albedrío tuvo algo que ver.",
    "m.c1-03": "Rara vez una cuestión ha dividido a los pensadores tan profundamente como ... . Mientras que algunos sostienen que ..., otros afirman que ... . No solo importa esto para ..., sino que también ... . Solo mediante ... podemos ... .",
