    "p.c1-04.1": "Adjunto encontrará el borrador revisado.",
    "p.c1-04.2": "Le escribo en referencia a su correo del 3 de mayo.",
    "p.c1-04.3": "Los hallazgos se resumen en la Tabla 2.",
    "p.c1-04.4": "Como se indicó anteriormente, la muestra era pequeña.",
    "p.c1-04.5": "Esto queda fuera del alcance del presente estudio.",
    "p.c1-04.6": "Se necesita más investigación.",
    "p.c1-04.7": "Si necesita más información, no dude en ponerse en contacto conmigo.",
    "p.c1-04.8": "En conclusión, las pruebas sugieren que...",
    "p.c1-04.9": "¿Podría aclarar qué entiende por este término?",
    "p.c1-04.10": "El plazo de presentación es el 30 de junio.",
    "p.c1-04.11": "Se ha argumentado que...",
    "p.c1-04.12": "Quedo a la espera de recibir sus comentarios.",
    "s.c1-04.1": "Se argumenta ampliamente que una terminología clara mejora la cohesión.",
    "s.c1-04.2": "Los datos se analizaron mediante la metodología descrita en el apéndice.",
    "s.c1-04.3": "Los hallazgos indican una fuerte relación entre el sueño y la memoria.",
    "s.c1-04.4": "Las fuentes deben citarse correctamente para evitar el plagio.",
    "s.c1-04.5": "La propuesta se presentó antes del plazo; en consecuencia, se revisó primero.",
    "s.c1-04.6": "Una oración ambigua debe reescribirse en lugar de explicarse.",
    "s.c1-04.7": "Además, las implicaciones de estos resultados van más allá de la educación.",
    "s.c1-04.8": "Se prepara un esquema conciso antes de escribir el primer borrador.",
    "s.c1-04.9": "El memorando aclara el alcance del proyecto para todos los departamentos.",
    "s.c1-04.10": "Parafrasear transmite la idea del autor sin copiar su redacción.",
    "s.c1-04.11": "Una corrección cuidadosa se considera esencial antes de la presentación.",
    "s.c1-04.12": "La bibliografía enumera todas las fuentes citadas en la tesis.",
    "d.c1-04.1": "Nir, he leído su borrador. La sección de metodología es sólida, pero la introducción es demasiado larga.",
    "d.c1-04.2": "Me lo temía. ¿Debería pasar los antecedentes a un apéndice?",
    "d.c1-04.3": "En parte. Resuma la historia en un párrafo y cite las fuentes clave en lugar de describirlas.",
    "d.c1-04.4": "Entendido. ¿Y el capítulo de hallazgos?",
    "d.c1-04.5": "Los datos están bien presentados, pero varias oraciones son ambiguas. Por ejemplo, la palabra significativo no queda clara aquí.",
    "d.c1-04.6": "Significación estadística. Aclararé la terminología.",
    "d.c1-04.7": "Bien. Además, la sección de implicaciones hace afirmaciones que van más allá del alcance de sus datos.",
    "d.c1-04.8": "¿Se refiere a la parte sobre la política nacional?",
    "d.c1-04.9": "Exactamente. Matice esas afirmaciones o elimínelas. Diga lo que indican los hallazgos, no lo que espera que demuestren.",
    "d.c1-04.10": "Parafrasearé la sección y bajaré el tono. ¿Algo más?",
    "d.c1-04.11": "Revise la bibliografía; faltan dos fuentes citadas en el capítulo tres. Luego corrija todo antes de presentarlo.",
    "d.c1-04.12": "Gracias. Le enviaré un borrador revisado antes del viernes.",
    "m.c1-04": "Este estudio examina ... . Los datos se recogieron de ... y se analizaron mediante ... . Los hallazgos indican que ... . Además, ... . En consecuencia, se sugiere que ... . Se discuten las implicaciones para ... .",
