    "w.c2-01.two-birds-one-stone": "matar dos pájaros de un tiro",
    "w.c2-01.sit-on-the-fence": "nadar entre dos aguas",
    "w.c2-01.pinch-of-salt": "tomar algo con pinzas",
    "w.c2-01.read-between-the-lines": "leer entre líneas",
    "p.c2-01.1": "Le estaría muy agradecido si pudiera...",
    "p.c2-01.2": "¿Me echas una mano?",
    "p.c2-01.3": "Falleció la primavera pasada.",
    "p.c2-01.4": "No es precisamente ciencia espacial.",
    "p.c2-01.5": "No nos vayamos por las ramas.",
    "p.c2-01.6": "Fue un poco decepcionante, por decirlo suavemente.",
    "p.c2-01.7": "Lamentamos informarle de que...",
    "p.c2-01.8": "Sin ofender, pero ese no es tu punto fuerte.",
    "p.c2-01.9": "Tiene un don para las palabras.",
    "p.c2-01.10": "Ahora mismo estoy entre un trabajo y otro.",
    "p.c2-01.11": "Y eso es decir poco.",
    "p.c2-01.12": "¡Cuánto tiempo sin verte!",
    "s.c2-01.1": "En un registro formal, rara vez usamos jerga o contracciones.",
    "s.c2-01.2": "Su respuesta fue diplomática, pero la insinuación era imposible de pasar por alto.",
    "s.c2-01.3": "Fue brusco respecto a los problemas, lo que a algunos colegas les pareció grosero.",
    "s.c2-01.4": "La palabra es correcta literalmente, pero su connotación es negativa.",
    "s.c2-01.5": "Los dos términos difieren solo en el matiz, no en el significado.",
    "s.c2-01.6": "Tienes que leer entre líneas en este correo.",
    "s.c2-01.7": "El periodista acuñó una frase que ahora todos usan.",
    "s.c2-01.8": "Llamar reestructuración a los despidos es un eufemismo clásico.",
    "s.c2-01.9": "Vamos al teatro muy de vez en cuando.",
    "s.c2-01.10": "Toma sus promesas con pinzas.",
    "s.c2-01.11": "Por la redacción de la carta, inferí que habían rechazado la propuesta.",
    "s.c2-01.12": "Las cifras publicadas son solo la punta del iceberg.",
    "d.c2-01.1": "He redactado su discurso para la reunión de personal. ¿Repasamos el registro?",
    "d.c2-01.2": "Sí. El primer párrafo parece demasiado formal para una reunión interna.",
    "d.c2-01.3": "De acuerdo. La frase inicial suena como un aviso legal; podríamos hacerla más directa.",
    "d.c2-01.4": "Directa, pero no brusca. La gente está inquieta por la fusión.",
    "d.c2-01.5": "Entonces una ligera atenuación podría funcionar mejor que un anuncio dramático.",
    "d.c2-01.6": "Exacto. Y por favor, quite los modismos deportivos. No todos los conocen.",
    "d.c2-01.7": "Bien. ¿Dejo el de leer entre líneas?",
    "d.c2-01.8": "Sí, ese se entiende en cualquier idioma. Además, cuidado con la palabra barato; tiene una connotación negativa.",
    "d.c2-01.9": "Usaré asequible en su lugar. El matiz es más amable.",
    "d.c2-01.10": "Bien. Una cosa más: el final insinúa despidos sin decirlo.",
    "d.c2-01.11": "Fue deliberado, una forma diplomática de preparar a la gente.",
    "d.c2-01.12": "Prefiero decirlo con claridad. Los eufemismos hacen que la gente confíe menos en ti, no más.",
    "m.c2-01": "Informal: Oye, no puedo ir esta noche, me surgió algo. Formal: Lamento comunicarle que no podré asistir esta noche debido a un compromiso imprevisto. La versión informal usa ..., mientras que la formal ... .",
